const modifierName=value=>({developmentCost:'development cost',procurementCost:'procurement cost',procurementTurns:'production time',operationStrength:'operation strength',supplyCapacity:'supply capacity',readinessRecovery:'readiness recovery',researchPerTurn:'R&D each turn',rightsRevenue:'rights revenue'}[value]||title(value));
