  const domains=collection(CAMPAIGN_DOMAINS);return (domains.length?domains:fallback).map((domain,index)=>typeof domain==='string'?{id:domain,name:title(domain),description:''}:{...domain,id:String(domain.id||domain.key||fallback[index]?.id||`domain-${index}`),name:domain.name||domain.label||title(domain.id||fallback[index]?.id),description:domain.description||domain.summary||''})
