 function developmentTreeHTML(){
  const state=getState(),nodes=getDevelopmentTree(state),completed=nodes.filter(node=>node.status==='complete').length,modifiers=getCampaignModifiers(state),branches=[...new Set(nodes.map(node=>node.branchId))];
  if(!nodes.some(node=>node.id===ui.techFocus))ui.techFocus=(nodes.find(node=>node.status==='available')||nodes.filter(node=>node.status==='locked').sort((a,b)=>a.missing.length-b.missing.length||a.depth-b.depth||a.cost-b.cost)[0]||nodes[0])?.id||null;
  const selected=nodes.find(node=>node.id===ui.techFocus)||nodes[0],unlocks=(selected?.equipmentIds||[]).map(getEquipment).filter(Boolean),requirements=(selected?.missing||[]).map(developmentRequirement),canUnlock=selected?.status==='available'&&state.researchPoints>=selected.cost;
  const tree=branches.map((branchId,branchIndex)=>{let branchDomId=`campaignBranch-${branchIndex}`,branchNodes=nodes.filter(node=>node.branchId===branchId).sort((a,b)=>a.depth-b.depth),branchComplete=branchNodes.filter(node=>node.status==='complete').length;return `<section class="campaign-tech-branch" aria-labelledby="${branchDomId}"><header><div><strong id="${branchDomId}">${esc(branchId)}</strong><small>${branchComplete}/${branchNodes.length} programs</small></div><b>Branch ${branchNodes[0]?.depth??0}-${branchNodes.at(-1)?.depth??0}</b></header><ol>${branchNodes.map(node=>{let selectedNode=node.id===ui.techFocus,statusLabel=node.status==='complete'?'Complete':node.status==='available'?'Available':'Locked',equipmentCount=node.equipmentIds.length;return `<li><button class="campaign-tech-node is-${node.status}" data-campaign-tech="${node.id}" aria-pressed="${selectedNode}"><span class="campaign-tech-node-mark" aria-hidden="true">${node.status==='complete'?'✓':node.depth}</span><span><strong>${esc(node.name)}</strong><small>${equipmentCount?`${equipmentCount} ${equipmentCount===1?'system':'systems'} linked`:`Campaign capability`}</small><em>${statusLabel}</em></span></button></li>`}).join('')}</ol></section>`}).join('');
  const detail=selected?`<article class="campaign-tech-detail"><header><div><small>${esc(selected.branchId)} &middot; depth ${selected.depth}</small><h4>${esc(selected.name)}</h4></div><span class="campaign-target-badge">${esc(title(selected.status))}</span></header><p>${esc(selected.description)}</p><div class="campaign-tech-effects">${unlocks.length?unlocks.map(item=>`<span>Unlocks ${esc(item.name)}</span>`).join(''):'<span>Campaign-wide capability</span>'}${Object.entries(selected.researchRequirements||{}).map(([branch,level])=>`<span>${esc(developmentRequirement(`${branch}:${level}`))}</span>`).join('')}</div><footer><span>${selected.status==='complete'?'Development completed.':requirements.length?`Requires ${esc(requirements.join(', '))}.`:state.researchPoints<selected.cost?`Need ${number(selected.cost-state.researchPoints)} more R&D.`:`Spend ${number(selected.cost)} R&D to complete immediately.`}</span><button class="campaign-secondary" data-campaign-tech-unlock="${selected.id}" ${canUnlock?'':'disabled'}>${selected.status==='complete'?'Complete':`${number(selected.cost)} R&D`}</button></footer></article>`:'';
  return `<div class="campaign-development-overview"><span><small>Programs complete</small><strong>${completed}/${nodes.length}</strong></span><span><small>R&amp;D invested</small><strong>${number(state.development.spent)}</strong></span><span><small>Cost modifier</small><strong>${Math.round((modifiers.developmentCost||0)*100)}%</strong></span></div>${researchProgramsHTML()}<div class="campaign-subheading"><strong>Branching programs</strong><small>Select a node to inspect its path</small></div><div class="campaign-tree-viewport"><div class="campaign-tech-tree">${tree}</div></div>${detail}`
 }

