  const availableRecommendations=nodes.filter(node=>node.status==='available').sort((a,b)=>(b.equipmentIds.length-a.equipmentIds.length)||(a.cost-b.cost)||a.depth-b.depth),blockedRecommendations=nodes.filter(node=>node.status==='locked').sort((a,b)=>a.missing.length-b.missing.length||a.depth-b.depth||(b.equipmentIds.length-a.equipmentIds.length)||a.cost-b.cost),recommendations=(availableRecommendations.length?availableRecommendations:blockedRecommendations).slice(0,3);
