  for(const branchId of branches){const slots=new Map(),top=branchLayout.get(branchId).top;for(const node of nodes.filter(item=>item.branchId===branchId).sort((a,b)=>a.depth-b.depth||a.name.localeCompare(b.name))){const slot=slots.get(node.depth)||0;slots.set(node.depth,slot+1);positions.set(node.id,{x:paddingX+node.depth*(nodeWidth+columnGap),y:top+slot*nodeStackGap})}}
  const links=nodes.flatMap(node=>(node.prerequisiteIds||[]).map(parentId=>{let from=positions.get(parentId),to=positions.get(node.id);if(!from||!to)return '';let x1=from.x+nodeWidth,y1=from.y+42,x2=to.x,y2=to.y+42,middle=(x1+x2)/2,onPath=pathIds.has(parentId)&&pathIds.has(node.id);return `<path class="${node.status==='complete'?'complete ':''}${onPath?'on-path':''}" d="M ${x1} ${y1} C ${middle} ${y1}, ${middle} ${y2}, ${x2} ${y2}"/>`})).join('');
  const stages=Array.from({length:maxDepth+1},(_,depth)=>`<div class="campaign-tree-stage" style="left:${paddingX+depth*(nodeWidth+columnGap)}px"><small>Stage ${depth+1}</small><strong>${stageLabels[depth]||`Tier ${depth+1}`}</strong></div>`).join('');
  const labels=branches.map(branchId=>{let lane=nodes.filter(node=>node.branchId===branchId),done=lane.filter(node=>node.status==='complete').length;return `<div class="campaign-tree-lane-label" style="left:16px;top:${branchLayout.get(branchId).top}px"><strong>${esc(title(branchId))}</strong><small>${done}/${lane.length} complete</small></div>`}).join('');
