  const detail=selected?`<article class="campaign-tech-detail campaign-tech-inspector"><header><div><small>${esc(title(selected.branchId))} &middot; stage ${selected.depth+1}</small><h4>${esc(selected.name)}</h4></div><span class="campaign-target-badge">${esc(title(selected.status))}</span></header><p>${esc(selected.description)}</p><div class="campaign-tech-inspector-grid"><section><small>Requirements</small>${requirementChecks.length?requirementChecks.map(item=>`<span class="${item.met?'met':'pending'}"><b>${item.met?'&#10003;':'!'}</b>${esc(item.label)}</span>`).join(''):'<span class="met"><b>&#10003;</b>No prerequisites</span>'}</section><section><small>What this opens</small>${unlocks.length?unlocks.map(item=>`<span><b>+</b>${esc(item.name)}</span>`).join(''):'<span><b>+</b>Campaign-wide capability</span>'}${leadsTo.map(node=>`<span><b>&rarr;</b>${esc(node.name)}</span>`).join('')}</section></div><footer><span>${selected.status==='complete'?'Development completed.':requirements.length?`Clear ${requirements.length} remaining requirement${requirements.length===1?'':'s'} to unlock this program.`:state.researchPoints<selected.cost?`Need ${number(selected.cost-state.researchPoints)} more R&D.`:`Ready now. Spend ${number(selected.cost)} R&D.`}</span><button class="campaign-primary" data-campaign-tech-unlock="${selected.id}" ${canUnlock?'':'disabled'}>${selected.status==='complete'?'Complete':`${number(selected.cost)} R&D`}</button></footer></article>`:'';
