 function onKeydown(event){
  if(debrief&&!debrief.hidden){if(event.key==='Escape'){event.preventDefault();closeDebrief()}else if(event.key==='Tab'){event.preventDefault();debrief.querySelector('#campaignDebriefClose')?.focus()}return}
  if(ui.overlay){
   if(event.key==='Escape'){event.preventDefault();closeOverlay();return}
   if(event.key==='Tab'){
    const focusable=[...panel.querySelectorAll('#campaignOverlay button:not([disabled]), #campaignOverlay [href], #campaignOverlay input:not([disabled]), #campaignOverlay select:not([disabled]), #campaignOverlay [tabindex]:not([tabindex="-1"])')].filter(node=>node.offsetParent!==null);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);
    if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}return
   }
  }
  if(event.key==='Escape'&&ui.active&&ui.mapMode){event.preventDefault();setMapMode(false);panel.querySelector('[data-campaign-map-mode]')?.focus();return}
  if(event.key==='Escape'&&ui.active&&ui.mode==='decisions'){event.preventDefault();ui.mode=ui.previousMode||'operations';ui.decisionChoice=null;render();focusConsoleStart()}
 }

